            "Those features suggest non-diabetic kidney disease, common in Indian biopsy series, so get a nephrology opinion for biopsy. [ISN 2023]",
            "Ultrasound KUB with post-void residual excludes obstruction and records size and echotexture - obstruction is the reversible miss. [KDIGO 2024]",
            "Look for the treatable layer: NSAIDs, unlabelled herbals, volume depletion, uncontrolled hypertension, recent contrast and infection. [KDIGO 2024]",
            "Bladder outlet obstruction belongs in that list, because a man of 56 with diabetes may have both BPH and a neurogenic bladder. [KDIGO 2024]",
            "Baseline panel: electrolytes, bicarbonate, calcium, phosphate, PTH, haemoglobin with iron studies, HbA1c and lipids. [KDIGO 2024]",
