        "10 to the power 4 CFU/mL is significant in pyelonephritis and in men, and any growth from a suprapubic aspirate is significant. [Campbell-Walsh 12e]",
        "Reciting only the 10 to the power 5 figure loses the mark - the lower thresholds are the examinable point. [Campbell-Walsh 12e]",
        "**Pyuria: 10 or more white cells per high power field** on centrifuged urine, or a positive leucocyte esterase, which detects the same cells. [Harrison 21e]",
        "Nitrite is specific for Enterobacterales but **negative with Enterococcus, Staph saprophyticus and Pseudomonas**, which lack nitrate reductase. [Harrison 21e]",
        "Nitrite needs 4 hours of bladder incubation to turn positive, so a negative dipstick nitrite does not exclude UTI in a frequent voider. [Harrison 21e]",
        "**Asymptomatic bacteriuria** is significant bacteriuria without symptoms - a colonisation state, not an infection. [IDSA 2019]",
        "Treat it **only in pregnancy and before a urological procedure that breaches the mucosa**, the two settings where trials showed benefit. [IDSA 2019]",
