        "Treating asymptomatic bacteriuria drives resistance and Clostridioides difficile without preventing a single symptomatic episode. [IDSA 2019]",
        "**Recurrent UTI: 2 or more infections in 6 months, or 3 or more in 12 months** - the count that triggers prophylaxis and imaging. [EAU 2024]",
        "**Relapse:** the same organism within 2 weeks of treatment - it suggests a stone, abscess, prostatitis or unresolved focus. [EAU 2024]",
        "**Reinfection:** a different organism, or a later interval - it points to behavioural and host factors, not to a hidden focus. [EAU 2024]",
        "**Catheter-associated UTI:** compatible symptoms with no other source plus 10 to the power 3 CFU/mL or more of a uropathogen. [CDC 2019]",
        "The count applies to a catheter specimen, or a midstream specimen if the catheter came out within 48 hours. [CDC 2019]",
        "**Cloudy or foul-smelling urine alone is not CAUTI** - every long-term catheter is colonised, so smell proves nothing. [CDC 2019]",
