        "**Non-contrast CT KUB is the gold standard**, with sensitivity about 95-98% and specificity about 96-98%. [EAU 2024]",
        "CT detects every stone type including uric acid, and diagnoses the alternative causes of the pain in the same scan. [EAU 2024]",
        "CT gives size, site, **Hounsfield density above 1000 HU predicting failure of shock wave lithotripsy**, and skin-to-stone distance. [EAU 2024]",
        "**Low-dose CT protocols cut the radiation dose to around 2 mSv**, so dose is no longer a reason to avoid the scan. [EAU 2024]",
