        "They constrict the afferent arteriole causing AKI, and retain sodium and water, worsening hypertension and heart failure. [NICE CKS 2023]",
        "They also cause hyperkalaemia, acute interstitial nephritis and papillary necrosis, so the harm is not only haemodynamic. [NICE CKS 2023]",
        "**The most useful prescription a family physician writes in CKD is often the one that stops the painkiller.** [NICE CKS 2023]",
        "**Metformin: full dose above eGFR 45, maximum 1000 mg/day at eGFR 30-44 and do not start there, and stop below 30.** [NICE CKS 2023]",
        "Hold metformin during acute illness or dehydration, and before iodinated contrast when eGFR is below 30. [NICE CKS 2023]",
        "The risk is **metformin-associated lactic acidosis** - rare, but with a mortality around 50% once established. [NICE CKS 2023]",
        "**Nitrofurantoin fails and accumulates below eGFR 30-45**, because it works only when concentrated in the urine. [NICE CKS 2023]",
        "It also causes pulmonary fibrosis and peripheral neuropathy on long-term use, and haemolysis in G6PD deficiency. [NICE CKS 2023]",
        "**Avoid aminoglycosides such as gentamicin and amikacin where possible**, since they accumulate in proximal tubular cells. [Aronoff 6e]",
        "If unavoidable, use once-daily extended-interval dosing at a full weight-based dose - gentamicin 5-7 mg/kg, amikacin 15 mg/kg. [Aronoff 6e]",
        "Keep the course to 5-7 days and never combine with another nephrotoxin, because toxicity is cumulative over days. [Aronoff 6e]",
        "Monitor the trough - gentamicin below 1 microgram/mL, amikacin below 5 micrograms/mL - and creatinine on alternate days. [Aronoff 6e]",
