        "**Avoid morphine, because morphine-6-glucuronide accumulates and causes sedation** - use fentanyl or buprenorphine instead. [Aronoff 6e]",
        "Halve co-trimoxazole below CrCl 30, and reduce acyclovir with generous hydration to prevent crystal nephropathy. [Aronoff 6e]",
