        "Give pyrazinamide and ethambutol thrice weekly below CrCl 30 or on dialysis, after the session; avoid streptomycin altogether. [ICMR 2023]",
        "Pyridoxine 10-25 mg daily is mandatory, because isoniazid neuropathy is far commoner in uraemia. [ICMR 2023]",
        "**In sepsis, give the full first dose immediately** and adjust only from the second dose onwards. [Aronoff 6e]",
        "Delaying or shrinking the first dose because of a raised creatinine is a serious and frequently examined error. [Aronoff 6e]",
        "Check for the interaction that causes the injury: an ACE inhibitor or ARB with an NSAID and a diuretic, the triple whammy. [NICE CKS 2023]",
